async function check(name,fn){const start=Date.now();try{const evidence=await fn();report.checks.push({host,name,status:'PASS',ms:Date.now()-start,evidence});console.log('PASS',host,name,JSON.stringify(evidence));}catch(e){report.checks.push({host,name,status:'FAIL',ms:Date.now()-start,error:e.stack});console.log('FAIL',host,name,e.message);await screenshot(name.replace(/[^a-z0-9]/gi,'-')+'-failure').catch(()=>{});await fs.writeFile(path.join(out,name.replace(/[^a-z0-9]/gi,'-')+'-failure-ui.txt'),await page.locator('body').innerText().catch(()=>''));}await flush();}
