 await check('House edits charter collection and reload',async()=>{await go('/house/');await page.locator('.house-node--house').click();const name=page.getByRole('textbox',{name:'The name of your house'});await name.fill('Synthetic QA House');await name.press('Tab');const aim=page.getByRole('textbox',{name:'Aim',exact:true});await aim.fill('Keep synthetic QA prose on this device.');await aim.press('Tab');await page.getByRole('textbox',{name:'New charter article'}).fill('All examples are synthetic.');await page.getByRole('button',{name:'Add article',exact:true}).click();await page.getByRole('button',{name:'Found a collection',exact:true}).click();const collection=page.getByRole('textbox',{name:'Collection name'});await collection.fill('Local QA collection');await collection.press('Tab');await page.getByRole('checkbox',{name:folioName,exact:true}).check();await until(async()=> (await readStore('meta')).some(v=>v.key==='house-state'&&v.value.house.name==='Synthetic QA House'&&v.value.collections.some(c=>c.name==='Local QA collection'&&c.folioIds.length===1)),'House state not persisted');await screenshot('10-house-collection');await page.getByRole('button',{name:'The register',exact:true}).click();await textPresent(page.locator('.house-register'),'Local QA collection');await screenshot('11-house-register');await page.reload({waitUntil:'domcontentloaded'});await until(async()=>await name.inputValue()==='Synthetic QA House','House name lost after reload');await page.locator('.house-node--house').click();ensure(await aim.inputValue()==='Keep synthetic QA prose on this device.','House aim lost after reload');ensure(await page.getByRole('textbox',{name:'Charter article',exact:true}).inputValue()==='All examples are synthetic.','House charter lost after reload');await screenshot('12-house-reloaded');return {state:(await readStore('meta')).find(v=>v.key==='house-state')};});
 await check('House mobile layout 390',()=>mobileCheck('13-house'));
 await check('library mobile layout 390',async()=>{await go('/library/');await page.getByRole('button',{name:new RegExp(folioName)}).waitFor({state:'visible'});return mobileCheck('14-library');});
 await check('editor mobile layout 390 and typing',async()=>{await page.getByRole('button',{name:new RegExp(folioName)}).click();const ed=await editor();await ed.click();await page.keyboard.press('ControlOrMeta+End');await page.keyboard.insertText(' Mobile writing at 390 pixels.');await textPresent(ed,'Mobile writing at 390 pixels.');return mobileCheck('15-editor');});
 await closeContext('apex-desktop');
 await openContext('https://www.twyne.love','www-mobile',{width:390,height:844},true);
 await check('www normal anonymous library onboarding editing reload',async()=>{await go('/library/');await textPresent(page.locator('body'),'No folios yet.');await screenshot('16-www-mobile-empty-library');await page.getByRole('link',{name:'Start writing →',exact:true}).click();await finishDossier('WWW synthetic QA notebook');const ed=await editor();await ed.click();await page.keyboard.press('ControlOrMeta+End');await page.keyboard.insertText(' WWW anonymous writing survives reload.');await until(async()=> (await readStore('folio-content')).some(v=>v.html.includes('WWW anonymous writing')),'www local autosave absent');await page.reload({waitUntil:'domcontentloaded'});await textPresent(await editor(),'WWW anonymous writing');return {finalURL:page.url(),separateOriginStorage:new URL(page.url()).host==='www.twyne.love',seeded:false};});
 await check('www mobile editor 390',()=>mobileCheck('17-www-editor'));
 await check('www House public normal UI',async()=>{await go('/house/');await page.locator('.house-node--house').click();const field=page.getByRole('textbox',{name:'The name of your house'});await field.fill('WWW synthetic House');await field.press('Tab');await until(async()=> (await readStore('meta')).some(v=>v.key==='house-state'&&v.value.house.name==='WWW synthetic House'),'www House save absent');await page.reload({waitUntil:'domcontentloaded'});await until(async()=>await field.inputValue()==='WWW synthetic House','www House reload absent');await screenshot('18-www-house');return {name:await field.inputValue()};});
 await closeContext('www-mobile');
}finally{
 if(context&&!context._closed)await context.close().catch(()=>{});
 await browser.close();report.finishedAt=new Date().toISOString();
 report.summary={passed:report.checks.filter(v=>v.status==='PASS').length,failed:report.checks.filter(v=>v.status==='FAIL').length,pageErrors:report.pageErrors.length,failedCoreAssets:report.failedRequests.filter(v=>v.category==='core-asset').length,badCoreAssets:report.badResponses.filter(v=>v.category==='core-asset').length};
 await flush();console.log('REPORT',path.join(out,'report.json'),JSON.stringify(report.summary));
}

