 await check('www normal anonymous library onboarding editing reload',async()=>{await go('/library/');await textPresent(page.locator('body'),'No folios yet.');await screenshot('16-www-mobile-empty-library');await page.getByRole('link',{name:'Start writing →',exact:true}).click();await finishDossier('WWW synthetic QA notebook');const ed=await editor();await ed.click();await page.keyboard.press('ControlOrMeta+End');await page.keyboard.insertText(' WWW anonymous writing survives reload.');await until(async()=> (await readStore('folio-content')).some(v=>v.html.includes('WWW anonymous writing')),'www local autosave absent');await page.reload({waitUntil:'domcontentloaded'});await textPresent(await editor(),'WWW anonymous writing');return {finalURL:page.url(),separateOriginStorage:new URL(page.url()).host==='www.twyne.love',seeded:false};});
 await check('www mobile editor 390',()=>mobileCheck('17-www-editor'));
 await check('www House public normal UI',async()=>{await go('/house/');await page.locator('.house-node--house').click();const field=page.getByRole('textbox',{name:'The name of your house'});await field.fill('WWW synthetic House');await field.press('Tab');await until(async()=> (await readStore('meta')).some(v=>v.key==='house-state'&&v.value.house.name==='WWW synthetic House'),'www House save absent');await page.reload({waitUntil:'domcontentloaded'});await until(async()=>await field.inputValue()==='WWW synthetic House','www House reload absent');await screenshot('18-www-house');return {name:await field.inputValue()};});
 await closeContext('www-mobile');
}finally{
 if(context&&!context._closed)await context.close().catch(()=>{});
 await browser.close();report.finishedAt=new Date().toISOString();
 report.summary={passed:report.checks.filter(v=>v.status==='PASS').length,failed:report.checks.filter(v=>v.status==='FAIL').length,pageErrors:report.pageErrors.length,failedCoreAssets:report.failedRequests.filter(v=>v.category==='core-asset').length,badCoreAssets:report.badResponses.filter(v=>v.category==='core-asset').length};
 await flush();console.log('REPORT',path.join(out,'report.json'),JSON.stringify(report.summary));
