 page.on('requestfailed',r=>report.failedRequests.push({host,url:r.url(),type:r.resourceType(),error:r.failure()?.errorText,category:category(r.url())}));
 page.on('response',async r=>{const u=r.url(),type=r.request().resourceType();if(r.status()>=400)report.badResponses.push({host,url:u,status:r.status(),type,category:category(u)});if(type==='document')report.documents.push({host,url:u,status:r.status(),headers:await r.allHeaders()});if(/twyne\.love\/(build|assets)\//.test(u))report.assets.push({host,url:u,status:r.status(),type});});
}
async function closeContext(label){await context.tracing.stop({path:path.join(out,label+'-trace.zip')});const video=page.video();await context.close();if(video)report.videos.push({label,path:path.relative(root,await video.path())});await flush();}
async function mobileCheck(label){
 await page.setViewportSize({width:390,height:844});await page.waitForTimeout(600);await screenshot(label+'-390');
 const result=await page.evaluate(()=>({viewport:innerWidth,documentWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth,overflows:[...document.querySelectorAll('body *')].filter(e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&(r.right>innerWidth+2||r.left<-2)}).slice(0,12).map(e=>({tag:e.tagName,class:e.className,left:e.getBoundingClientRect().left,right:e.getBoundingClientRect().right}))}));
 ensure(result.documentWidth<=390,'Page overflows 390px: '+JSON.stringify(result));return result;
}
try{
 await openContext('https://twyne.love','apex-desktop');
 await check('empty library and visible new-folio onboarding',async()=>{await go('/library/');await textPresent(page.locator('body'),'No folios yet.');await screenshot('01-empty-library');await page.getByRole('link',{name:'Start writing →',exact:true}).click();await finishDossier(folioName);await screenshot('02-editor-initial');const folios=await readStore('folios');ensure(folios.some(f=>f.name===folioName),'Folio missing from IndexedDB');return {url:page.url(),folios,seeded:false};});
 if(!await page.locator('.ProseMirror').first().isVisible().catch(()=>false)){
  await check('explicit direct IndexedDB fallback',async()=>{await go('/library/');await page.evaluate(async({folioName,marker})=>{const now=Date.now(),id='production-qa-local-synthetic';const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('twyne',4);r.onupgradeneeded=()=>{for(const [name,keyPath] of [['folios','id'],['folio-content','folioId'],['brief','folioId'],['comments','id'],['personas','id'],['meta','key'],['ai-settings','key'],['lix-blob','key'],['voice-notes','id'],['models','id'],['ai-usage-events','eventKey'],['writing-activity-detail','activityKey']]){if(!r.result.objectStoreNames.contains(name)){const s=r.result.createObjectStore(name,{keyPath});if(name==='ai-usage-events')s.createIndex('by-occurred-at','occurredAt');if(name==='writing-activity-detail')s.createIndex('by-day','day');}}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});await new Promise((resolve,reject)=>{const tx=db.transaction(['folios','folio-content','brief','meta'],'readwrite');tx.objectStore('folios').put({id,name:folioName,type:'draft',createdAt:now,updatedAt:now});tx.objectStore('folio-content').put({folioId:id,html:'<p>'+marker+'</p>',updatedAt:now});tx.objectStore('brief').put({folioId:id,brief:{answers:{workingTitle:folioName,format:'Essay',audience:'QA readers',goal:'Verify local editing',tone:'Plain',constraints:'Synthetic only',successSignal:'Survive reload'},attachments:[],completedAt:now,updatedAt:now},updatedAt:now});tx.objectStore('meta').put({key:'active-folio-id',value:id,updatedAt:now});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close();},{folioName,marker});await go('/editor/');await textPresent(await editor(),marker);return {seeded:true,source:'idb.ts DB version 4; direct transaction; no dev-source import'};});
 }
 await check('editor typing autosave and reload',async()=>{const ed=await editor();await ed.click();await page.keyboard.press('ControlOrMeta+End');await page.keyboard.insertText(' Local autosave survives a production reload.');await textPresent(ed,'Local autosave survives');await until(async()=> (await readStore('folio-content')).some(v=>v.html.includes('Local autosave survives')),'Typed prose did not save to IndexedDB');await screenshot('03-editor-typed');await page.reload({waitUntil:'domcontentloaded'});await textPresent(await editor(),'Local autosave survives');return {stored:(await readStore('folio-content')).map(v=>({folioId:v.folioId,html:v.html,format:v.format,hasTypstSource:!!v.typstSource}))};});
 await check('source tab local editing and proof compiler',async()=>{await page.getByRole('button',{name:'Source',exact:true}).click();const cm=page.locator('.typst-source .cm-content');await cm.waitFor({state:'visible',timeout:20000});await textPresent(cm,'Local autosave survives');await screenshot('04-source');await cm.click();await page.keyboard.press('ControlOrMeta+End');await page.keyboard.insertText('\n\nSource QA remains local.\n');await page.getByRole('button',{name:'Apply source',exact:true}).click();await page.getByRole('button',{name:'Proof',exact:true}).click();const proof=page.locator('.typst-proof img').first();await proof.waitFor({state:'visible',timeout:45000});ensure(await proof.evaluate(e=>e.complete&&e.naturalWidth>0),'Proof image not decoded');const pages=await page.locator('.typst-proof img').count();const status=await page.locator('.typst-status').innerText();await screenshot('05-proof');await page.getByRole('button',{name:'Write',exact:true}).click();await textPresent(await editor(),'Source QA remains local.');await page.reload({waitUntil:'domcontentloaded'});await textPresent(await editor(),'Source QA remains local.');return {pages,status,sourceAppliedAndReloaded:true};});
 await check('idle voice desk close reopen and responsive editor',async()=>{const desk=page.getByRole('complementary',{name:'Live voice desk'});const cycles=[];for(let i=0;i<3;i++){await page.getByRole('button',{name:'Open Live voice desk',exact:true}).click();await desk.waitFor({state:'visible'});if(i===0)await screenshot('06-voice-idle');await desk.getByRole('button',{name:'Close voice desk',exact:true}).click();await desk.waitFor({state:'hidden'});const response=await page.evaluate(()=>new Promise(r=>setTimeout(()=>r('responsive'),50)));ensure(response==='responsive','Renderer did not respond');const ed=await editor();await ed.click();await page.keyboard.press('ControlOrMeta+End');await page.keyboard.insertText(' Still writing '+i+'.');await textPresent(ed,'Still writing '+i+'.');cycles.push(i);}await screenshot('07-voice-closed-editor');return {cycles,microphoneUsed:false,conversationStarted:false};});
 await check('library saved preview and reopening',async()=>{await go('/library/');const card=page.getByRole('button',{name:new RegExp(folioName)});await card.waitFor({state:'visible'});await textPresent(card,'Synthetic production QA');await screenshot('08-library-saved');await card.click();await textPresent(await editor(),'Still writing 2.');return {previewAndReopen:true};});
 await check('second new folio via editor UI',async()=>{await page.getByRole('button',{name:'New folio',exact:true}).click();await page.getByPlaceholder('Folio name',{exact:true}).fill('Production QA — second folio');await page.getByRole('button',{name:'Create',exact:true}).click();await page.getByPlaceholder('A working title — anything you can carry across a desk').waitFor({state:'visible'});await screenshot('09-new-folio-dossier');const folios=await readStore('folios');ensure(folios.some(f=>f.name==='Production QA — second folio'),'Second folio metadata missing');await go('/library/');await page.getByRole('button',{name:new RegExp(folioName)}).click();await textPresent(await editor(),'Still writing 2.');return {folios:folios.map(f=>({id:f.id,name:f.name})),dossierStarted:true,firstFolioPreserved:true};});
 await check('House edits charter collection and reload',async()=>{await go('/house/');await page.locator('.house-node--house').click();const name=page.getByRole('textbox',{name:'The name of your house'});await name.fill('Synthetic QA House');await name.press('Tab');const aim=page.getByRole('textbox',{name:'Aim',exact:true});await aim.fill('Keep synthetic QA prose on this device.');await aim.press('Tab');await page.getByRole('textbox',{name:'New charter article'}).fill('All examples are synthetic.');await page.getByRole('button',{name:'Add article',exact:true}).click();await page.getByRole('button',{name:'Found a collection',exact:true}).click();const collection=page.getByRole('textbox',{name:'Collection name'});await collection.fill('Local QA collection');await collection.press('Tab');await page.getByRole('checkbox',{name:folioName,exact:true}).check();await until(async()=> (await readStore('meta')).some(v=>v.key==='house-state'&&v.value.house.name==='Synthetic QA House'&&v.value.collections.some(c=>c.name==='Local QA collection'&&c.folioIds.length===1)),'House state not persisted');await screenshot('10-house-collection');await page.getByRole('button',{name:'The register',exact:true}).click();await textPresent(page.locator('.house-register'),'Local QA collection');await screenshot('11-house-register');await page.reload({waitUntil:'domcontentloaded'});await until(async()=>await name.inputValue()==='Synthetic QA House','House name lost after reload');await page.locator('.house-node--house').click();ensure(await aim.inputValue()==='Keep synthetic QA prose on this device.','House aim lost after reload');ensure(await page.getByRole('textbox',{name:'Charter article',exact:true}).inputValue()==='All examples are synthetic.','House charter lost after reload');await screenshot('12-house-reloaded');return {state:(await readStore('meta')).find(v=>v.key==='house-state')};});
