   const request=r.request(),url=cleanURL(r.url()),type=request.resourceType(),headers=await r.allHeaders();
   const item={label,url,status:r.status(),type,method:request.method(),contentType:headers['content-type'],accessControlAllowOrigin:headers['access-control-allow-origin']||null,accessControlAllowCredentials:headers['access-control-allow-credentials']||null};
   if(type==='document')report.documents.push({...item,csp:headers['content-security-policy']||null});
   if(r.status()>=400)report.badResponses.push({...item,expectedAnonymous:r.status()===401&&new URL(r.url()).pathname==='/api/session'});
   if(['fetch','xhr'].includes(type)||/\/api\/|\/v1\/public\//.test(new URL(r.url()).pathname))report.endpointResponses.push(item);
   if(['stylesheet','script'].includes(type)&&/notorganic\.info/.test(new URL(r.url()).hostname)){
    try{const body=await r.body();const text=body.toString('utf8');report.assets.push({...item,bytes:body.length,sha256:createHash('sha256').update(body).digest('hex'),accountCompanionCSS:text.includes('.product-account-actions')});}catch(error){report.assets.push({...item,bodyReadError:error.message})}
   }
  })().catch(error=>report.consoleErrors.push({label,observerError:error.message}));pending.add(promise);promise.finally(()=>pending.delete(promise));
 });
}
async function close(){if(!context)return;await Promise.allSettled([...pending]);await context.tracing.stop({path:path.join(out,label+'-trace.zip')});report.traces.push(label+'-trace.zip');const video=page.video();await context.close();if(video)report.videos.push({label,path:path.relative(out,await video.path())});context=null;await flush()}

try{
 for(const [currentLabel,viewport,mobile] of [['desktop',{width:1440,height:1000},false],['mobile390',{width:390,height:844},true]]){
  await open(currentLabel,viewport,mobile);
  await check('Not Organic new account companion landing',async()=>{
   await go('https://notorganic.info/');
   await page.locator('.account-strip').waitFor({state:'visible'});
   ensure(await page.locator('.product-account-actions a').count()===8,'Expected eight product sign-in/create-account links');
   const header=page.locator('.site-header').getByRole('link',{name:/Sign in/});
   ensure((await header.getAttribute('href')).includes('action=signin'),'Header sign-in route missing');
   await until(()=>Promise.resolve(report.assets.some(a=>a.accountCompanionCSS&&a.status===200)),'New account companion CSS not observed');
   const state=await describe('notorganic-landing');ensure(state.documentWidth<=viewport.width,'Landing horizontal page overflow');
   await page.locator('.site-header').scrollIntoViewIfNeeded();
   return {url:state.url,accountCompanionVisible:true,productActions:8,viewport:state.width,documentWidth:state.documentWidth};
  });
  await check('Not Organic header sign-in reaches public login UI',async()=>{
   await page.locator('.site-header').getByRole('link',{name:/Sign in/}).click();
   await page.waitForURL(u=>u.hostname==='id.notorganic.info',{timeout:30000});
   await page.getByRole('textbox',{name:'Account handle'}).waitFor({state:'visible',timeout:30000});
   const state=await describe('notorganic-login');ensure(state.documentWidth<=viewport.width,'Login horizontal page overflow');
   ensure(state.inputs.every(i=>!i.hasValue),'Fresh login unexpectedly contains input values');
   return {url:state.url,handleInputVisible:true,credentialsEntered:false,documentWidth:state.documentWidth};
  });
  await check('Public identity root anonymous login',async()=>{
   await go('https://id.notorganic.info/');
   await page.getByRole('textbox',{name:'Account handle'}).waitFor({state:'visible',timeout:30000});
   const state=await describe('identity-root');return {url:state.url,anonymousLoginVisible:true};
  });
  await check('Twyne companion signup entry UI without submitting',async()=>{
   await go('https://id.notorganic.info/?action=signup&product=twyne');
   await page.getByRole('heading',{name:'Create your Not Organic account'}).waitFor({state:'visible',timeout:30000});
   const state=await describe('twyne-companion-signup');ensure((await page.locator('body').innerText()).includes('Twyne'),'Twyne product context missing');
   return {url:state.url,signupUIVisible:true,accountCreated:false};
  });
  await check('Twyne public landing and sign-in panel',async()=>{
   await go('https://twyne.love/');await describe('twyne-landing');
   await go('https://twyne.love/editor/?auth=1');
   const button=page.getByRole('button',{name:/Continue with Not Organic|Sign in with Not Organic/});
   await button.waitFor({state:'visible',timeout:30000});
   const state=await describe('twyne-signin-panel');return {url:state.url,button:await button.innerText(),enabled:await button.isEnabled()};
  });
  await check('Twyne Not Organic button public authorization navigation',async()=>{
   await page.getByRole('button',{name:/Continue with Not Organic|Sign in with Not Organic/}).click();
   await page.waitForURL(u=>u.hostname==='id.notorganic.info',{timeout:30000});
   await page.getByRole('textbox',{name:'Account handle'}).waitFor({state:'visible',timeout:30000});
   const state=await describe('twyne-provider-login');
   ensure((await page.locator('body').innerText()).includes('Twyne'),'Provider login lost Twyne context');
   return {url:state.url,providerLoginReached:true,productContext:'Twyne',credentialsEntered:false,authorizationApproved:false,tokenExchanged:false};
  });
  await close();
 }
}catch(error){report.fatalError={message:error.message,stack:error.stack};console.error('FATAL',error.message);process.exitCode=1}
finally{
 await close().catch(error=>{report.captureCloseError=error.message});await browser.close();report.finishedAt=new Date().toISOString();
 report.summary={passed:report.checks.filter(c=>c.status==='PASS').length,failed:report.checks.filter(c=>c.status==='FAIL').length,pageErrors:report.pageErrors.length,unexpectedHttpErrors:report.badResponses.filter(r=>!r.expectedAnonymous).length,expectedAnonymous401:report.badResponses.filter(r=>r.expectedAnonymous).length,failedRequests:report.failedRequests.length,blockedRequests:report.blockedRequests.length};
 await flush();console.log('REPORT',path.join(out,'report.json'),JSON.stringify(report.summary));
}

