/* Shared identity: the generated raster silhouette stays identical in both themes. */
:root {
  color-scheme: light;
  --page: #f7f8f0;
  --ink: #102519;
  --forest-soft: #3f5849;
  --water: #3f6b55;
  --brand-ink: #103720;
  --focus: #805012;
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --page: #10271f;
  --ink: #eef3e7;
  --forest-soft: #b9cbbd;
  --water: #abc9ae;
  --line: #496052;
  --brand-ink: #c5e765;
  --focus: #e7a0b4;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --page: #10271f;
    --ink: #eef3e7;
    --forest-soft: #b9cbbd;
    --water: #abc9ae;
    --line: #496052;
    --brand-ink: #c5e765;
    --focus: #e7a0b4;
  }
}
html, body, .principles article, .exits article, .offer-grid article { background: var(--page); }
body { color: var(--ink); }
