import { chromium } from 'playwright';
import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';

const root = path.dirname(new URL(import.meta.url).pathname);
const runName = process.env.QA_RUN_NAME || ('navigation-repro-'+new Date().toISOString().replace(/[:.]/g,'-'));
const out = path.join(root, runName);
await fs.mkdir(out,{recursive:false});
await fs.copyFile(new URL(import.meta.url),path.join(out,'executed-replay.mjs'));
const report={startedAt:new Date().toISOString(),target:'Twyne FULL v0.23.2 SHA 866b80f',scope:'Published JS; isolated anonymous synthetic local UI; no microphone, auth exchange, private content, or paid AI',checks:[],pageErrors:[],consoleErrors:[],failedRequests:[],badResponses:[],blockedPaidRequests:[],documents:[],assets:[],videos:[]};
const browser=await chromium.launch({headless:true,executablePath:path.join(root,'chromium-wrapper.py')});
let context,page,host;
const marker='Synthetic production QA: the red notebook rests beside the window.';
const folioName='Production QA — synthetic notebook';
function category(url){if(/posthog|analytics|telemetry|doubleclick|google-analytics/i.test(url))return 'analytics';if(/^(chrome|moz)-extension:/.test(url))return 'browser-extension';if(/twyne\.love\/(build|assets)\//.test(url))return 'core-asset';if(/twyne\.love/.test(url))return 'app';return 'external';}
async function flush(){await fs.writeFile(path.join(out,'report.json'),JSON.stringify(report,null,2));}
async function screenshot(name){await page.screenshot({path:path.join(out,name+'.png'),fullPage:true});}
async function check(name,fn){const start=Date.now();try{const evidence=await fn();report.checks.push({host,name,status:'PASS',ms:Date.now()-start,evidence});console.log('PASS',host,name,JSON.stringify(evidence));}catch(e){report.checks.push({host,name,status:'FAIL',ms:Date.now()-start,error:e.stack});console.log('FAIL',host,name,e.message);await screenshot(name.replace(/[^a-z0-9]/gi,'-')+'-failure').catch(()=>{});await fs.writeFile(path.join(out,name.replace(/[^a-z0-9]/gi,'-')+'-failure-ui.txt'),await page.locator('body').innerText().catch(()=>''));}await flush();}
function ensure(value,message){if(!value)throw new Error(message);}
async function go(route){await page.goto(host+route,{waitUntil:'domcontentloaded',timeout:45000});}
async function readStore(store){return page.evaluate(async store=>{const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('twyne');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const value=await new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});db.close();return value;},store);}
async function until(fn,message,ms=15000){const end=Date.now()+ms;while(Date.now()<end){if(await fn())return;await page.waitForTimeout(300)}throw new Error(message);}
async function textPresent(locator,text){await locator.waitFor({state:'visible',timeout:20000});await until(async()=> (await locator.innerText()).includes(text),'Missing text: '+text);}
async function editor(){const ed=page.locator('.ProseMirror').first();await ed.waitFor({state:'visible',timeout:30000});return ed;}
async function finishDossier(name){
 const steps=[['A working title — anything you can carry across a desk',name],['Essay','Essay'],['A skeptical, smart reader who needs the argument made plainly','Local QA readers'],['Convince them, inform them, move them, or change how they think.','Verify anonymous local editing'],['Calm, exact, and a little sharp where it matters','Plain'],['Keep claims tied to evidence, avoid jargon, preserve the anecdote in the second paragraph.','Synthetic local test only'],['A reader can state the thesis back to us and knows why it matters.','Text survives reload']];
 for(const [placeholder,value] of steps){const input=page.getByPlaceholder(placeholder,{exact:true});await input.waitFor({state:'visible',timeout:15000});await input.fill(value);await page.getByRole('button',{name:'Next',exact:true}).click();}
 await page.getByRole('navigation',{name:'Folio sections'}).getByRole('button',{name:'IX',exact:true}).click();
 await page.getByPlaceholder('Paste an outline, a stalled draft, research notes, source quotes — whatever the room should hold while you write.').fill(marker);
 await page.getByRole('button',{name:'Next',exact:true}).click();
 await page.getByRole('button',{name:'Send to press',exact:true}).click();
 await page.getByRole('button',{name:'Continue to the editor →',exact:true}).click({timeout:20000});
 await textPresent(await editor(),marker);
}
async function openContext(origin,label,viewport={width:1440,height:1000},mobile=false){
 host=origin;
 context=await browser.newContext({viewport,locale:'en-CA',isMobile:mobile,hasTouch:mobile,recordVideo:{dir:path.join(out,label+'-video'),size:viewport}});
 await context.tracing.start({screenshots:true,snapshots:true,sources:true});
 // Abort only expenditure APIs. No fake successful AI/auth responses are supplied.
 await context.route('**/*',async route=>{const u=route.request().url();if(/\/(api\/(live|voice|provider|research|chat)|v1\/(judgement|chat|live|audio))(\/|$|\?)/i.test(u)){report.blockedPaidRequests.push({host,url:u,method:route.request().method()});await route.abort('blockedbyclient');}else await route.continue();});
 page=await context.newPage();page.setDefaultTimeout(12000);
 page.on('pageerror',e=>report.pageErrors.push({host,page:page.url(),message:e.message,stack:e.stack}));
 page.on('console',m=>{if(m.type()==='error')report.consoleErrors.push({host,page:page.url(),text:m.text()});});
 page.on('requestfailed',r=>report.failedRequests.push({host,url:r.url(),type:r.resourceType(),error:r.failure()?.errorText,category:category(r.url())}));
 page.on('response',async r=>{const u=r.url(),type=r.request().resourceType();if(r.status()>=400)report.badResponses.push({host,url:u,status:r.status(),type,category:category(u)});if(type==='document')report.documents.push({host,url:u,status:r.status(),headers:await r.allHeaders()});if(/twyne\.love\/(build|assets)\//.test(u))report.assets.push({host,url:u,status:r.status(),type});});
}
async function closeContext(label){if(!context)return;await context.tracing.stop({path:path.join(out,label+'-trace.zip')});const video=page.video();await context.close();if(video)report.videos.push({label,path:path.relative(root,await video.path())});context=null;await flush();}
async function mobileCheck(label){
