   const textAfter=await (await editor()).innerText();
   const observation={host:origin,attempt,tail:tail.trim(),visibleBefore,visibleAfter:textAfter.includes(tail.trim()),settledBaselinePresent:textAfter.includes('Settled baseline survives.'),navigationAndReopenMs:Date.now()-started,stored:(await readStore('folio-content')).map(v=>({folioId:v.folioId,html:v.html})),reopenedText:textAfter};
   report.observations.push(observation);await screenshot(label+'-rapid-navigation-'+attempt);
   ensure(observation.visibleAfter,'Visible final text was lost after immediate full navigation and reopening; see observations');
   return observation;
  });
  await closeContext(label+'-navigation');
 }
}catch(error){report.fatalError={message:error.message,stack:error.stack};console.error('FATAL',error.message);process.exitCode=1;}
finally {
 if(context)await closeContext('interrupted-context').catch(()=>{});
